        (2.32120314063337385e-03, 3.45176889180800757e-04, 1.65808505360197117e-01, 6.34618981378206378e-03, -5.46638864417632559e-05, -3.05164222869649731e-03, -2.38846353613204714e-03, 6.61726821846878597e-04, 2.23660520101632621e-01, -6.27940147901036652e-03, -9.52204866525511182e-04, -3.86942670629561725e-01,),
    ),
)

@inline function _nas_nxy_pc_finite(x::Float64)
    return isfinite(x) ? x : 0.0
end

function _nas_nxy_pc_alpha_from_cb(Cb, aspect::Float64)
    Cb isa AbstractMatrix || return 0.0
    size(Cb, 1) >= 2 && size(Cb, 2) >= 2 || return 0.0
    D11 = Float64(Cb[1, 1])
    D22 = Float64(Cb[2, 2])
    D11 > 0.0 && D22 > 0.0 || return 0.0
    val = (1.0 / max(aspect, 1.0)) * (D11 / D22)^0.25
    return isfinite(val) ? val : 0.0
end

@inline function _nas_nxy_pc_value(feature::Symbol, aspect::Float64, skew::Float64, taper::Float64,
                                   alpha::Float64, beta::Float64, gamma::Float64, delta::Float64,
                                   frac0::Float64, frac90::Float64, fracp45::Float64,
                                   fracm45::Float64, fracpm45::Float64, frac090::Float64,
                                   pm45_signed::Float64, pm45_balance::Float64,
                                   orient_cos2::Float64, orient_sin2::Float64,
                                   orient_cos4::Float64, orient_sin4::Float64)
    aspect2 = aspect * aspect
    aspect3 = aspect2 * aspect
    inv_aspect = 1.0 / max(aspect, 1e-300)
    inv_aspect2 = 1.0 / max(aspect2, 1e-300)
    inv_aspect3 = 1.0 / max(aspect3, 1e-300)
    feature === :one && return 1.0
    feature === :aspect && return aspect
    feature === :aspect2 && return aspect2
    feature === :aspect3 && return aspect3
    feature === :inv_aspect && return inv_aspect
    feature === :inv_aspect2 && return inv_aspect2
    feature === :inv_aspect3 && return inv_aspect3
    feature === :skew && return skew
    feature === :skew_aspect && return skew * aspect
    feature === :skew_aspect2 && return skew * aspect2
    feature === :taper && return taper
    feature === :taper_aspect && return taper * aspect
    feature === :taper_aspect2 && return taper * aspect2
    feature === :nemeth_alpha && return alpha
    feature === :nemeth_beta && return beta
    feature === :nemeth_gamma && return gamma
    feature === :nemeth_delta && return delta
    feature === :frac0 && return frac0
    feature === :frac90 && return frac90
    feature === :fracp45 && return fracp45
    feature === :fracm45 && return fracm45
    feature === :fracpm45 && return fracpm45
    feature === :frac090 && return frac090
    feature === :pm45_signed && return pm45_signed
    feature === :pm45_balance && return pm45_balance
    feature === :orient_cos2 && return orient_cos2
    feature === :orient_sin2 && return orient_sin2
    feature === :orient_cos4 && return orient_cos4
    feature === :orient_sin4 && return orient_sin4
    feature === :pm45_signed_aspect && return pm45_signed * aspect
    feature === :pm45_signed_aspect2 && return pm45_signed * aspect2
    feature === :pm45_signed_inv_aspect && return pm45_signed * inv_aspect
    feature === :pm45_balance_aspect && return pm45_balance * aspect
    feature === :pm45_balance_aspect2 && return pm45_balance * aspect2
    feature === :orient_sin2_aspect && return orient_sin2 * aspect
    feature === :orient_sin2_aspect2 && return orient_sin2 * aspect2
    feature === :orient_sin2_inv_aspect && return orient_sin2 * inv_aspect
    feature === :fracp45_aspect && return fracp45 * aspect
    feature === :fracm45_aspect && return fracm45 * aspect
    feature === :fracpm45_aspect && return fracpm45 * aspect
    feature === :nemeth_alpha_aspect && return alpha * aspect
    feature === :nemeth_beta_aspect && return beta * aspect
    feature === :nemeth_gamma_aspect && return gamma * aspect
    feature === :nemeth_delta_aspect && return delta * aspect
    feature === :nemeth_gamma_aspect2 && return gamma * aspect2
    feature === :nemeth_delta_aspect2 && return delta * aspect2
    feature === :nemeth_alpha_pm45_signed && return alpha * pm45_signed
    feature === :nemeth_alpha_pm45_balance && return alpha * pm45_balance
    feature === :nemeth_gamma_pm45_signed && return gamma * pm45_signed
    feature === :nemeth_delta_pm45_signed && return delta * pm45_signed
    feature === :nemeth_gamma_pm45_signed_aspect && return gamma * pm45_signed * aspect
    feature === :nemeth_delta_pm45_signed_aspect && return delta * pm45_signed * aspect
    feature === :nemeth_beta_pm45_balance && return beta * pm45_balance
    feature === :nemeth_beta_pm45_balance_aspect && return beta * pm45_balance * aspect
    return 0.0
end

function _nas_nxy_pc_feature_values(features, metrics, Cb;
                                    frac0::Float64=0.0,
                                    frac90::Float64=0.0,
                                    fracp45::Float64=0.0,
                                    fracm45::Float64=0.0,
                                    fracpm45::Float64=NaN,
                                    frac090::Float64=NaN,
                                    pm45_signed::Float64=NaN,
                                    pm45_balance::Float64=NaN,
                                    orient_cos2::Float64=0.0,
                                    orient_sin2::Float64=0.0,
                                    orient_cos4::Float64=0.0,
                                    orient_sin4::Float64=0.0,
                                    nemeth_alpha::Float64=NaN,
                                    nemeth_beta::Float64=NaN,
                                    nemeth_gamma::Float64=NaN,
                                    nemeth_delta::Float64=NaN)
    aspect = _nas_nxy_pc_finite(Float64(metrics.aspect))
    skew = _nas_nxy_pc_finite(Float64(metrics.skew))
    taper = _nas_nxy_pc_finite(Float64(metrics.taper))
    alpha = isfinite(nemeth_alpha) ? nemeth_alpha : _nas_nxy_pc_alpha_from_cb(Cb, aspect)
    beta = isfinite(nemeth_beta) ? nemeth_beta : _nas_nxy_pc_finite(Float64(metrics.beta))
    gamma = isfinite(nemeth_gamma) ? nemeth_gamma : _nas_nxy_pc_finite(Float64(metrics.gamma))
    delta = isfinite(nemeth_delta) ? nemeth_delta : _nas_nxy_pc_finite(Float64(metrics.delta))
    fpm45 = isfinite(fracpm45) ? fracpm45 : fracp45 + fracm45
    f090 = isfinite(frac090) ? frac090 : frac0 + frac90
    signed = isfinite(pm45_signed) ? pm45_signed : fracp45 - fracm45
    balance = isfinite(pm45_balance) ? pm45_balance : abs(signed)
    return ntuple(i -> _nas_nxy_pc_value(features[i], aspect, skew, taper,
        alpha, beta, gamma, delta,
        frac0, frac90, fracp45, fracm45, fpm45, f090,
        signed, balance, orient_cos2, orient_sin2, orient_cos4, orient_sin4),
        length(features))
end

function _nas_nxy_pc_base_matrix!(K12::AbstractMatrix, coords::AbstractMatrix,
                                  resultant::Float64, values)
    cache = Dict{Symbol,Matrix{Float64}}()
    for (term, coeffs) in _NAS_NXY_PC_BASE_COEFFS
        c = 0.0
        @inbounds for i in eachindex(values)
            c += Float64(coeffs[i]) * Float64(values[i])
        end
        abs(c) > 0.0 || continue
        candidate = get!(cache, term) do
            _nas_shape_kg_candidate(coords, term)
        end
        K12 .+= (resultant * c) .* candidate
    end
    return K12
end

function _nas_nxy_pc_scores(values)
    scores = zeros(Float64, length(_NAS_NXY_PC_MATS))
    z_l2 = 0.0
    z_max = 0.0
    active_count = 0
    for pc in eachindex(_NAS_NXY_PC_MATS)
        scores[pc] = _NAS_NXY_PC_INTERCEPTS[pc]
    end
    @inbounds for i in eachindex(values)
        _NAS_NXY_PC_PATCH_ACTIVE[i] || continue
        scale = max(_NAS_NXY_PC_PATCH_SCALES[i], 1e-300)
        z = (Float64(values[i]) - _NAS_NXY_PC_PATCH_MEANS[i]) / scale
        z_l2 += z * z
        z_max = max(z_max, abs(z))
        active_count += 1
        for pc in eachindex(_NAS_NXY_PC_MATS)
            scores[pc] += _NAS_NXY_PC_SCORE_COEFFS[pc][i] * z
        end
    end
    return scores, sqrt(z_l2), z_max, active_count
end

function _nas_nxy_pc_patch_matrix!(K12::AbstractMatrix, resultant::Float64, values)
    scores, _, _, _ = _nas_nxy_pc_scores(values)
    for pc in eachindex(_NAS_NXY_PC_MATS)
        score = scores[pc]
        pcmat = _NAS_NXY_PC_MATS[pc]
        @inbounds for i in 1:12, j in 1:12
            K12[i, j] += resultant * score * pcmat[i][j]
        end
    end
    return K12
end

function nastran_nxy_pc_patch_descriptor_metrics(
    coords::AbstractMatrix,
    Cb=nothing;
    frac0::Float64=0.0,
    frac90::Float64=0.0,
    fracp45::Float64=0.0,
    fracm45::Float64=0.0,
    fracpm45::Float64=NaN,
    frac090::Float64=NaN,
    pm45_signed::Float64=NaN,
    pm45_balance::Float64=NaN,
    orient_cos2::Float64=0.0,
    orient_sin2::Float64=0.0,
    orient_cos4::Float64=0.0,
    orient_sin4::Float64=0.0,
    nemeth_alpha::Float64=NaN,
    nemeth_beta::Float64=NaN,
    nemeth_gamma::Float64=NaN,
    nemeth_delta::Float64=NaN,
)
    metrics = _nas_shape_kg_metrics(coords, Cb)
    patch_values = _nas_nxy_pc_feature_values(_NAS_NXY_PC_PATCH_FEATURES, metrics, Cb;
        frac0=frac0, frac90=frac90, fracp45=fracp45, fracm45=fracm45,
        fracpm45=fracpm45, frac090=frac090, pm45_signed=pm45_signed,
        pm45_balance=pm45_balance, orient_cos2=orient_cos2, orient_sin2=orient_sin2,
        orient_cos4=orient_cos4, orient_sin4=orient_sin4, nemeth_alpha=nemeth_alpha,
        nemeth_beta=nemeth_beta, nemeth_gamma=nemeth_gamma, nemeth_delta=nemeth_delta)
    scores, z_l2, z_max, active_count = _nas_nxy_pc_scores(patch_values)
    score_l2 = sqrt(sum(abs2, scores))
    return (
        z_l2=z_l2,
        z_rms=active_count > 0 ? z_l2 / sqrt(active_count) : 0.0,
        z_max=z_max,
        active_count=active_count,
        score_l2=score_l2,
        score_max=isempty(scores) ? 0.0 : maximum(abs.(scores)),
    )
end

function geometric_stiffness_quad4_nastran_nxy_pc_patch_synth(
    coords::AbstractMatrix,
    sigma_mem::AbstractVector,
    h::Float64,
    Cb=nothing;
    frac0::Float64=0.0,
    frac90::Float64=0.0,
    fracp45::Float64=0.0,
    fracm45::Float64=0.0,
    fracpm45::Float64=NaN,
    frac090::Float64=NaN,
    pm45_signed::Float64=NaN,
    pm45_balance::Float64=NaN,
    orient_cos2::Float64=0.0,
    orient_sin2::Float64=0.0,
    orient_cos4::Float64=0.0,
    orient_sin4::Float64=0.0,
    nemeth_alpha::Float64=NaN,
    nemeth_beta::Float64=NaN,
    nemeth_gamma::Float64=NaN,
    nemeth_delta::Float64=NaN,
)
    Kg = zeros(24, 24)
    h > 1e-30 || return Kg
    length(sigma_mem) >= 3 || return Kg
    resultant = Float64(sigma_mem[3]) * h
    abs(resultant) > 0.0 || return Kg
    metrics = _nas_shape_kg_metrics(coords, Cb)
    base_values = _nas_nxy_pc_feature_values(_NAS_NXY_PC_BASE_FEATURES, metrics, Cb;
        frac0=frac0, frac90=frac90, fracp45=fracp45, fracm45=fracm45,
        fracpm45=fracpm45, frac090=frac090, pm45_signed=pm45_signed,
        pm45_balance=pm45_balance, orient_cos2=orient_cos2, orient_sin2=orient_sin2,
        orient_cos4=orient_cos4, orient_sin4=orient_sin4, nemeth_alpha=nemeth_alpha,
        nemeth_beta=nemeth_beta, nemeth_gamma=nemeth_gamma, nemeth_delta=nemeth_delta)
    patch_values = _nas_nxy_pc_feature_values(_NAS_NXY_PC_PATCH_FEATURES, metrics, Cb;
        frac0=frac0, frac90=frac90, fracp45=fracp45, fracm45=fracm45,
        fracpm45=fracpm45, frac090=frac090, pm45_signed=pm45_signed,
        pm45_balance=pm45_balance, orient_cos2=orient_cos2, orient_sin2=orient_sin2,
        orient_cos4=orient_cos4, orient_sin4=orient_sin4, nemeth_alpha=nemeth_alpha,
        nemeth_beta=nemeth_beta, nemeth_gamma=nemeth_gamma, nemeth_delta=nemeth_delta)
    K12 = zeros(12, 12)
    _nas_nxy_pc_base_matrix!(K12, coords, resultant, base_values)
    _nas_nxy_pc_patch_matrix!(K12, resultant, patch_values)
    tdofs = (1, 2, 3, 7, 8, 9, 13, 14, 15, 19, 20, 21)
    @inbounds for a in 1:12, b in 1:12
        Kg[tdofs[a], tdofs[b]] = K12[a, b]
    end
    return Kg
end

function geometric_stiffness_quad4_nastran_nxy_pc_patch_synth(
    coords::AbstractMatrix,
    sigma_mem_gp::AbstractMatrix,
    h::Float64,
    Cb=nothing; kwargs...
)
    size(sigma_mem_gp, 2) >= 3 || return zeros(24, 24)
    inv_ngp = 1.0 / max(size(sigma_mem_gp, 1), 1)
    sigma_mem = [
        sum(@view sigma_mem_gp[:, 1]) * inv_ngp,
        sum(@view sigma_mem_gp[:, 2]) * inv_ngp,
        sum(@view sigma_mem_gp[:, 3]) * inv_ngp,
    ]
    return geometric_stiffness_quad4_nastran_nxy_pc_patch_synth(
        coords, sigma_mem, h, Cb; kwargs...)
end
